WITH churn_customers AS ( SELECT c.c_customer_sk, c.c_customer_id, dr.d_date AS last_review_date, date_diff('day', dr.d_date, current_date) AS days_since_review FROM customer c INNER JOIN date_dim dr ON c.c_last_review_date = dr.d_date_sk WHERE date_diff('day', dr.d_date, current_date) > 365 ), store_sales_agg AS ( SELECT ss.ss_customer_sk AS cust_sk, SUM(ss.ss_net_profit) AS store_net_profit, SUM(ss.ss_ext_discount_amt) AS store_total_discount, SUM(ss.ss_ext_sales_price) AS store_total_sales FROM store_sales ss INNER JOIN date_dim ds ON ss.ss_sold_date_sk = ds.d_date_sk INNER JOIN churn_customers cc ON ss.ss_customer_sk = cc.c_customer_sk WHERE ds.d_date <= cc.last_review_date GROUP BY ss.ss_customer_sk ), web_sales_agg AS ( SELECT ws.ws_bill_customer_sk AS cust_sk, SUM(ws.ws_net_profit) AS web_net_profit, SUM(ws.ws_ext_discount_amt) AS web_total_discount, SUM(ws.ws_ext_sales_price) AS web_total_sales FROM web_sales ws INNER JOIN date_dim dw ON ws.ws_sold_date_sk = dw.d_date_sk INNER JOIN churn_customers cc ON ws.ws_bill_customer_sk = cc.c_customer_sk WHERE dw.d_date <= cc.last_review_date GROUP BY ws.ws_bill_customer_sk ) SELECT cc.c_customer_id, cc.days_since_review, COALESCE(ss.store_net_profit, 0) + COALESCE(ws.web_net_profit, 0) AS total_net_profit, (COALESCE(ss.store_total_discount, 0) + COALESCE(ws.web_total_discount, 0)) / NULLIF((COALESCE(ss.store_total_sales, 0) + COALESCE(ws.web_total_sales, 0)), 0) AS discount_ratio, CASE WHEN COALESCE(ss.store_net_profit, 0) + COALESCE(ws.web_net_profit, 0) >= 20000 THEN 'High' WHEN COALESCE(ss.store_net_profit, 0) + COALESCE(ws.web_net_profit, 0) >= 5000 THEN 'Medium' ELSE 'Low' END AS profit_tier, RANK() OVER (ORDER BY COALESCE(ss.store_net_profit, 0) + COALESCE(ws.web_net_profit, 0) DESC) AS profit_rank FROM churn_customers cc LEFT JOIN store_sales_agg ss ON cc.c_customer_sk = ss.cust_sk LEFT JOIN web_sales_agg ws ON cc.c_customer_sk = ws.cust_sk ORDER BY profit_rank LIMIT 20
